// Hermes P3 / WP3.1 — ModelRegistry `registerModel` calldata tests.
//
// The Rule-1-critical property is that the calldata is BYTE-EXACT against the live ABI.
// The expected vector is generated by foundry `cast` (the same tool the deploy script
// uses), so this test fails loudly if the hand-rolled encoder ever drifts:
//
//   cast calldata \
//     'registerModel(string,string,string,string,uint256,uint256,(string,string[],string[],uint256,string,string[]))' \
//     gemma gguf 1.0 QmTest 1000 0 '(A model,[],[],0,MIT,[nlp,chat])'
use super::*;

/// The exact `cast calldata` output for the fixture below (selector 0x49dc4e2f).
const CAST_FIXTURE: &str = "";

#[test]
fn register_model_calldata_matches_cast_byte_for_byte() {
    let meta = ModelMetadata {
        description: "A model".into(),
        license: "MIT".into(),
        tags: vec!["nlp".into(), "chat".into()],
    };
    let got = register_model_calldata("gemma", "gguf", "1.0", "QmTest", 1000, 0, &meta);
    assert_eq!(hex::encode(&got), CAST_FIXTURE, "calldata must match `cast` exactly");
}

#[test]
fn selector_is_the_live_register_model_selector() {
    // keccak256(sig)[..4] == the selector `cast sig` reported (0x49dc4e2f).
    assert_eq!(hex::encode(selector(REGISTER_MODEL_SIG)), "49dc4e2f");
}

#[test]
fn empty_tags_and_metadata_still_encode_and_decode_a_valid_offset_head() {
    // A bare registration (no tags/description) must still be well-formed: 7 head words,
    // each dynamic offset in range, and the tuple's own head present.
    let got = register_model_calldata("m", "gguf", "1", "QmX", 42, 0, &ModelMetadata::default());
    assert_eq!(&got[..4], &selector(REGISTER_MODEL_SIG));
    let args = &got[4..];
    // sizeBytes is the 5th head word (index 4) and inline == 42.
    let size_word = &args[4 * 32..5 * 32];
    assert_eq!(u128::from_be_bytes(size_word[16..32].try_into().unwrap()), 42);
    // The metadata offset (7th head word) points within the calldata.
    let meta_off = u128::from_be_bytes(args[6 * 32 + 16..7 * 32].try_into().unwrap()) as usize;
    assert!(meta_off < args.len(), "metadata tuple offset in range");
}

#[test]
fn the_registration_fee_is_a_tenth_of_a_salt() {
    // 0.1 SALT (1e18 wei per SALT). Mirrors REGISTRATION_FEE in ModelRegistry.sol.
    assert_eq!(REGISTRATION_FEE_WEI, 100_000_000_000_000_000);
}
